function ConversationEvidence({sources}:{sources?:Message['evidence']}){
 const safe=safeConversationEvidence(sources);
 if(!safe.length)return null;
 const card=(source:typeof safe[number])=><article key={source.id}><span className="eyebrow">LOCAL SOURCE CANDIDATE · REVIEW SCOPE</span><h3><a href={source.url} target="_blank" rel="noreferrer">{source.title} ↗</a></h3><p>{source.summary}</p><small>{source.publisher} · {source.jurisdiction} · Published {source.publishedAt??'not established'} · Retrieved {new Date(source.retrievedAt).toLocaleDateString('en-IN')}</small><p className="fine-print">{source.limitations}</p></article>;
 return <div className="research-results conversation-evidence" aria-label="Retrieved local evidence candidates">{card(safe[0])}{safe.length>1&&<details className="details-block"><summary>Also found {safe.length-1} other local source candidate{safe.length===2?'':'s'}</summary><div className="research-results">{safe.slice(1).map(card)}</div></details>}</div>;
}

function GeminiPackageInterpretation({candidates}:{candidates:TentativeStructuredCandidate[]}){
 if(!candidates.length)return null;
 return <section className="model-candidate-results research-results" aria-label="Tentative package interpretation"><div><span className="eyebrow">STRUCTURED MODEL READINGS · UNVERIFIED</span><h3>Possible package readings</h3><p>Gemini reconstructed these from the supplied evidence. They remain separate from package facts and are not used in calculations.</p></div>{candidates.map(candidate=><article key={candidate.candidateId}><span className="badge neutral">{candidate.kind}</span><h4>{candidate.field}</h4><p><strong>{candidate.numericValue===null?candidate.proposedValue:[candidate.numericValue,candidate.unit].filter(Boolean).join(' ')}</strong>{candidate.basis&&<> · per {candidate.basis.amount} {candidate.basis.unit}</>}{candidate.kind==='nutrient'&&!candidate.basis&&<> · basis unresolved</>}</p>{candidate.normalizedEntity&&candidate.normalizedEntity!==candidate.field&&<small>Normalized as {candidate.normalizedEntity}</small>}<p className="fine-print">{candidate.uncertainty}</p><details className="details-block"><summary>Evidence used</summary>{candidate.supportingSpans.map((span,index)=><p key={'text-'+span.kind+'-'+span.id+'-'+index}><span className="fine-print">{span.kind} · {span.id}</span><br/><q>{span.quote}</q></p>)}{(candidate.visualEvidence??[]).map((evidence,index)=><p key={'image-'+evidence.imageId+'-'+index}><span className="fine-print">Photo · {evidence.imageId} · Gemini-reported text, unverified</span>{evidence.region&&<><br/><span className="fine-print">Relative region {Math.round(evidence.region.x*100)}%, {Math.round(evidence.region.y*100)}%, {Math.round(evidence.region.width*100)}% × {Math.round(evidence.region.height*100)}%</span></>}<br/><q>{evidence.visibleText}</q></p>)}</details></article>)}</section>;
}
function selectGeminiImageAssets(images:ImageAsset[],pkg:PackageData){
 const ranked=images.map((image,index)=>{
  const lines=pkg.observations.filter(observation=>observation.origin==='ocr'&&observation.imageId===image.id&&observation.field==='ocr-line');
  const text=lines.map(line=>line.text.toLowerCase()).join(' ');
  const roleScore=image.role==='nutrition'||image.role==='ingredients'?8:image.role==='front'?4:0;
  const contentScore=(/nutrition|energy|carbohyd|protein|sodium|fat|sugar/.test(text)?6:0)+(/ingredient|contains|allergen|may contain/.test(text)?6:0);
  return {image,index,score:Math.min(lines.length,20)+roleScore+contentScore};
 });
 return ranked.sort((a,b)=>b.score-a.score||a.index-b.index).slice(0,3).map(item=>item.image);
}

async function compactGeminiImage(source:Blob){
 const bitmap=await createImageBitmap(source);
 try{
  for(const edge of [2000,1700,1400]){
   const scale=Math.min(1,edge/Math.max(bitmap.width,bitmap.height));
   const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
   const context=canvas.getContext('2d');if(!context)throw new Error('Your browser could not prepare this image for Gemini.');
   context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);
   for(const quality of [0.86,0.76,0.66]){
    const compressed=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Image compression failed.')),'image/jpeg',quality));
    if(compressed.size<=900_000)return compressed;
   }
  }
 }finally{bitmap.close();}
 throw new Error('A selected photo could not be reduced to the safe size limit. Remove it or use a smaller image.');
}

